window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"mdTEVHQsg6s","speaker":"Muhammed Jallow","role":"Vice President","country":"Gambia","region":"Africa","url":"https://www.youtube.com/watch?v=mdTEVHQsg6s","date":"20260924","title":"🇬🇲 Gambia - Vice President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1303,"words":3082,"counts":{"claims":38,"promises":3,"attacks":0},"topics":[{"topic":"UN reform","share":0.1019,"seconds":133},{"topic":"UNGA greetings","share":0.0573,"seconds":75},{"topic":"conflict prevention","share":0.0544,"seconds":71},{"topic":"Gambia transition","share":0.0528,"seconds":69},{"topic":"Gambia democracy","share":0.0526,"seconds":68},{"topic":"Gambia peacebuilding","share":0.0521,"seconds":68},{"topic":"Gambia climate","share":0.0513,"seconds":67},{"topic":"multilateral system","share":0.0512,"seconds":67},{"topic":"Cuba","share":0.0492,"seconds":64},{"topic":"Palestine","share":0.049,"seconds":64},{"topic":"UNGA principles","share":0.0488,"seconds":64},{"topic":"multilateralism","share":0.0488,"seconds":64},{"topic":"Gambia energy","share":0.0483,"seconds":63},{"topic":"Gambia development","share":0.0475,"seconds":62},{"topic":"Moroccan Sahara","share":0.0475,"seconds":62},{"topic":"crimes against humanity","share":0.0472,"seconds":62},{"topic":"Sudan","share":0.0469,"seconds":61},{"topic":"LDC technology","share":0.0468,"seconds":61},{"topic":"Gambia elections","share":0.0466,"seconds":61}],"timeline":[[5,65,null],[65,140,"UNGA greetings"],[141,204,"UNGA principles"],[206,273,"multilateral system"],[274,337,"multilateralism"],[338,407,"Gambia transition"],[408,479,"conflict prevention"],[480,548,"Gambia peacebuilding"],[549,610,"Sudan"],[612,680,"Gambia democracy"],[682,742,"Gambia elections"],[743,805,"Gambia development"],[807,873,"Gambia climate"],[875,938,"Gambia energy"],[939,1000,"LDC technology"],[1002,1073,"UN reform"],[1076,1137,"crimes against humanity"],[1139,1202,"Palestine"],[1204,1268,"Cuba"],[1269,1330,"Moroccan Sahara"],[1333,1394,"UN reform"]],"stances":{"UNGA greetings":"The speaker extends warm greetings to the new President of the General Assembly and expresses appreciation for the predecessor, the Secretary-General, and the Deputy Secretary-General.","UNGA principles":"Muhammed Jallow emphasizes that the UN embodies sovereign equality and asserts that disputes must be resolved through dialogue to sustain development, peace, and human rights.","multilateral system":"Muhammed Jallow argues that the current global system is failing due to divisions and debt, but asserts that The Gambia's experience demonstrates multilateralism can still deliver results.","multilateralism":"Muhammed Jallow argues that multilateralism requires willingness to negotiate and compromise rather than unanimity, citing The Gambia's experience with constitutional uncertainty in 2017 as evidence of progress through political will.","Gambia transition":"Muhammed Jallow asserts that UN preventive diplomacy successfully supported Gambia's peaceful democratic transition and argues this model should be applied globally to other fragile nations.","conflict prevention":"Muhammed Jallow argues that preventing conflict is more cost-effective than managing its consequences and calls for stronger early warning systems, timely mediation, and sustained resources.","Gambia peacebuilding":"Muhammed Jallow supports a stronger, better-resourced Peacebuilding Commission and reaffirms support for UN peacebuilding operations while emphasizing the safety of personnel.","Sudan":"Muhammed Jallow states that the Gambia is profoundly concerned by the ongoing conflict in Sudan and instability in the Sahel, emphasizing that peace requires development and comprehensive international responses.","Gambia democracy":"Muhammed Jallow states that the Gambia's democratic journey since 2017 has been guided by a broad understanding of security and has involved rebuilding institutions, strengthening the rule of law, and implementing transitional justice.","Gambia elections":"Muhammed Jallow states that the Gambia is committed to holding peaceful, credible, and inclusive elections in 2026 in accordance with national laws.","Gambia development":"Muhammed Jallow states that the Gambia is expanding opportunities for women and youth while highlighting global economic challenges facing developing nations.","Gambia climate":"Muhammed Jallow states that climate change is an immediate threat to The Gambia and outlines the country's response through investment in renewable energy and resilience measures.","Gambia energy":"Muhammed Jallow states that Gambia has achieved 90% electricity access and is expanding solar energy while urging international support for climate finance.","LDC technology":"Muhammed Jallow asserts that developing countries must actively participate in global technology governance and innovation rather than remaining passive consumers, emphasizing the need for inclusive and responsible AI governance.","UN reform":"Muhammed Jallow supports United Nations reform to strengthen its capacity, correct historical injustices, and enable meaningful participation for developing countries.","crimes against humanity":"Muhammed Jallow supports the General Assembly's decision to move towards a convention on crimes against humanity and highlights The Gambia's leading role in advancing this process.","Palestine":"Muhammed Jallow calls for the protection of civilians, respect for international humanitarian law, and a two-state solution for Israel and Palestine.","Cuba":"The Gambia calls for an end to economic, commercial, and financial sanctions against Cuba.","Moroccan Sahara":"Muhammed Jallow supports Moroccan autonomy initiatives and calls for stakeholders to work toward a sustainable political solution."},"claims":[{"t":79,"quote":"Mr. President, allow me at the outset to congratulate you most warmly on your election as President of the 84th Session of the General Assembly.","topic":"UNGA greetings","kind":"fact"},{"t":120,"quote":"I also wish to place on record the Gambia's appreciation for the Secretary General, Mr. Antonio Guterres, and Deputy Secretary General, Amina Mohammed, whose steady and principled leadership through years of compounding global crises have done much to keep the flame of multilateral cooperation alight, even as the winds against it have grown fiercer.","topic":"UNGA greetings","kind":"fact"},{"t":194,"quote":"Eight decades later, we must ask ourselves whether we have remained faithful to that insight.","topic":"UNGA principles","kind":"fact"},{"t":212,"quote":"Wars have become more protracted with devastating humanitarian consequences.","topic":"multilateral system","kind":"fact"},{"t":222,"quote":"developing countries facing intensifying debt burden, climate vulnerabilities, huge gaps between commitments made and implementation","topic":"multilateral system","kind":"fact"},{"t":264,"quote":"The Gambia had the honor of chairing the Second Committee at a time of profound disagreement over some of the most consequential economic and development issues before us.","topic":"multilateral system","kind":"self_credit"},{"t":328,"quote":"In 2017, our country stood at a moment of acute constitutional uncertainty. The democratic choice of the Gambian people faced a grave challenge.","topic":"multilateralism","kind":"fact"},{"t":340,"quote":"the preventive diplomacy of the United Nations, working in partnership with African Union and ECOWAS, helped uphold the will of the Gambian people and support a peaceful democratic transition.","topic":"Gambia transition","kind":"fact"},{"t":396,"quote":"resources available to respond to crisis remain far below what is","topic":"Gambia transition","kind":"fact"},{"t":441,"quote":"It is infinitely less costly in human, political, and financial terms to to prevent conflict than to manage its consequences after violence has begun.","topic":"conflict prevention","kind":"fact"},{"t":480,"quote":"The Gambia has experienced the value of peacebuilding firsthand. Since our democratic transition, this Peacebuilding Commission and the Secretary-General's Peacebuilding Forum have been steadfast partners in our nationally led efforts to strengthen institutions, advance trans-transitional justice, and consolidate peace.","topic":"Gambia peacebuilding","kind":"fact"},{"t":523,"quote":"We also reaffirm our support for United Nations peacebuilding operations and pay tribute to the men and women who serve under the UN flag, including Gambian military and police personnel who have contributed with distinction to international peace and security.","topic":"Gambia peacebuilding","kind":"self_credit"},{"t":559,"quote":"the ongoing conflict in Sudan remains a matter of profound concern to the Gambia, together with continued instability across part of the Sahel.","topic":"Sudan","kind":"fact"},{"t":572,"quote":"The suffering of civilians in the affected conflict zones globally demands sustained international attention and renewed diplomatic efforts towards the escalation, dialogue, and a durable in the Sahel and other conflict zones.","topic":"Sudan","kind":"fact"},{"t":631,"quote":"Mr. President, in the Gambia, this understanding has guided our democratic journey from 2017 to date.","topic":"Gambia democracy","kind":"fact"},{"t":638,"quote":"We have undertaken the develop difficult work of rebuilding institutions, strengthening the rule of law, expanding access to justice, and confronting the legacy of past human rights violations.","topic":"Gambia democracy","kind":"self_credit"},{"t":649,"quote":"Our transitional justice process continues through implementation of the recommendation of the Truth, Reconciliation, and Reparations We have strengthened institutional accountability, established a special prosecution office to advance investigations and prosecution arising from the TRRC process.","topic":"Gambia democracy","kind":"self_credit"},{"t":682,"quote":"On the 5th of December, 2026, the Gambian people will again exercise their sovereign democratic right to choose their president.","topic":"Gambia elections","kind":"fact"},{"t":696,"quote":"Our government is committed to ensuring that the elections are peaceful, credible, and inclusive and conducted in accordance with our constitution, national laws, and democratic standards.","topic":"Gambia elections","kind":"self_credit"},{"t":743,"quote":"We are expanding opportunities for women and young people, improving lives, and strengthening the human capital upon which our future depends.","topic":"Gambia development","kind":"fact"},{"t":758,"quote":"The global economic environment, Mr. President, remains particularly difficult for developing countries with declining official development assistance, high borrowing costs, disruptions in international trade, inflationary pressures, and food and energy insecurity, narrowing fiscal space, and threatening development gains.","topic":"Gambia development","kind":"fact"},{"t":849,"quote":"Coastal erosion, changing rainfall patterns, pressure on water resources, food insecurity, and environmental degradation are already affecting our communities and livelihoods.","topic":"Gambia climate","kind":"fact"},{"t":875,"quote":"National electricity access already 90% with universal access targeted by the end of 2026.","topic":"Gambia energy","kind":"number"},{"t":881,"quote":"We are expanding our solar energy in schools and health facilities, modernizing our electric electric network, and advancing a 150-MW solar park.","topic":"Gambia energy","kind":"fact"},{"t":965,"quote":"As the Gambia prepares to assume greater leadership within the global coordination bureau of the LDC group","topic":"LDC technology","kind":"fact"},{"t":977,"quote":"limited productive capacity, high debt burdens, climate vulnerability, narrow export base, technological gaps, and restricted access to affordable finance","topic":"LDC technology","kind":"fact"},{"t":1002,"quote":"Migration contributes significantly to development, cultural exchange, and human progress.","topic":"UN reform","kind":"fact"},{"t":1010,"quote":"irregular migration continues to expose young people and vulnerable populations to exploitation, trafficking, abuse, and tragic loss","topic":"UN reform","kind":"fact"},{"t":1043,"quote":"We recognize the constraints facing the organization was limited with limited resources and increasing demands.","topic":"UN reform","kind":"fact"},{"t":1091,"quote":"The Gambia is proud of its leading role alongside Mexico in advancing this process through more than three decades of patient negotiation.","topic":"crimes against humanity","kind":"self_credit"},{"t":1139,"quote":"The Gambia commends Ghana for its historic resolution on declaration of trafficking of enslaved Africans and racialized chattel enslavement of Africans as the gravest crime against humanity","topic":"Palestine","kind":"fact"},{"t":1177,"quote":"We reaffirm the legitimate and inalienable rights of the Palestinian people, including their right to membership of United Nation","topic":"Palestine","kind":"fact"},{"t":1215,"quote":"On Cuba, we reiterate our long-standing call for an end to the economic, commercial, and financial sanctions.","topic":"Cuba","kind":"fact"},{"t":1230,"quote":"The Gambia also reaffirms its adherence to the one-China policy and values its partnership with the People's Republic of China","topic":"Cuba","kind":"fact"},{"t":1269,"quote":"The real initiatives of Moroccan autonomy, the Moroccan-Nigeria gas pipeline, the Atlantic African initiative amongst others have provided realistic pathways to finding a lasting political solution to the dispute over the Moroccan Sahara by giving people the development, human rights, security, and stability they need.","topic":"Moroccan Sahara","kind":"fact"},{"t":1289,"quote":"the Gambia welcomed the Kingdom of Morocco's continuous commitment to the ceasefire, full cooperation with MINURSO, and all also stakeholders all stakeholders in line with the resolution 2797 and other relevant","topic":"Moroccan Sahara","kind":"fact"},{"t":1360,"quote":"The Gambia stands ready to work with every member state to renew the promise that brought the nations of the world together.","topic":"UN reform","kind":"fact"},{"t":1367,"quote":"My country's own journey has taught us that countries and institutions can evolve from moments of profound uncertainty and further build and create increased trust and confidence.","topic":"UN reform","kind":"fact"}],"promises":[{"t":696,"quote":"Our government is committed to ensuring that the elections are peaceful, credible, and inclusive and conducted in accordance with our constitution, national laws, and democratic standards.","topic":"Gambia elections","kind":"promise"},{"t":859,"quote":"However, we are responding with determination by investing in renewable energy, coastal resilience, mangrove restoration, disaster risk reduction, early warning systems, water security, and nature-based nature-based solutions.","topic":"Gambia climate","kind":"promise"},{"t":987,"quote":"We will continue to advocate for full implementation of the Doha of action.","topic":"LDC technology","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":5,"topic":null,"text":"The assembly will hear an address by His Excellency Muhammad Jallow, Vice President of the Republic of the Gambia. I request protocol to escort His Excellency and invite him to address the &gt;&gt; I was about to have an accident in the middle of the road again. Mr. President, Dr. Rahman, Excellency Antonio Guterres, Secretary General of the United Nations, your Majesties, Excellencies, heads of state and government, heads of delegation, distinguished delegates, ladies and it is a distinct honor for me to address this assembly on behalf of His Excellency Mr."},{"t":65,"topic":"UNGA greetings","text":"Adama Barrow, President of the Republic of the Gambia. I bring to this hall the warm greetings of the government and people of the Gambia together with our enduring friendship, solidarity, and goodwill to all nations represented here. Mr. President, allow me at the outset to congratulate you most warmly on your election as President of the 84th Session of the General Assembly. The Gambia assures you of our full and constructive cooperation as we guide our collective work under the timely theme you have chosen, restoring trust and managing transformation so that the United Nations can deliver for all. That theme speaks directly to the moment in which we meet. Permit me also to express our profound appreciation to your predecessor, Ms. Analena Baerbock, for the dedication, dignity, and determination with which she presided over the 80th session of the General Assembly. I also wish to place on record the Gambia's appreciation for the Secretary General, Mr. Antonio Guterres, and Deputy Secretary General, Amina Mohammed, whose steady and principled leadership through years of compounding global crises have done much to keep the flame of multilateral cooperation alight, even as the winds against it have grown fiercer."},{"t":141,"topic":"UNGA principles","text":"We wish them well and they as they complete their tenure at the end of this year. Mr. President, few institutions embody the principle of sovereign equality as visibly as this With the within these walls, differences in power, wealth, and influence may shape the realities our nations confront, but they do not confer a greater claim to membership or And perhaps more than anywhere else, this assembly reminds us of a simple Our differences are real, but so is our This is why this organization was created with the understanding that disputes must be resolved through dialogue. Human dignity must be protected and that nations must work together if development, peace, and human rights are to be sustained. In other words, that our common future required common institutions. Eight decades later, we must ask ourselves whether we have remained faithful to that insight. And perhaps more importantly, do we still trust one another enough to act on it?"},{"t":206,"topic":"multilateral system","text":"Because today, Mr. President, trust is being tested. Geopolitical divisions are widening. Wars have become more protracted with devastating humanitarian consequences. Respect for the United Nations Charter and international law is under visible With developing countries facing intensifying debt burden, climate vulnerabilities, huge gaps between commitments made and implementation, and feeling of marginalization and inadequate representation in the global Therefore, the task before us is building stronger, better equipped, representative, responsive, and an effective multilateral system and global financial architecture that delivers for all nations and regions. Mr. President, The Gambia's own experience within the this organization gives us grounds for optimism. We have seen within the this very institution that multilateralism can still deliver. During the 80th session of the General The Gambia had the honor of chairing the Second Committee at a time of profound disagreement over some of the most consequential economic and development issues before us."},{"t":274,"topic":"multilateralism","text":"That experience reminded us that multilateralism does not require unanimity on every issue. It requires the willingness to remain at the table, to listen, negotiate, and correct to make compromise. Our experience demonstrate that in this periods of deep disagreement, progress remains possible when member states approach negotiations with political will, mutual respect, and assertions of Mr. President, the stakes are perhaps greatest in international peace and one of the foremost purposes for which this organization was created. If diplomacy can bring countries together to find common ground on difficult questions on global development, then surely we can summon the same political courage to prevent conflicts, resolve wars, and build lasting peace. The Gambia speaks on this not merely from principle, but from experience. In 2017, our country stood at a moment of acute constitutional uncertainty. The democratic choice of the Gambian people faced a grave challenge."},{"t":338,"topic":"Gambia transition","text":"At that critical moment, the preventive diplomacy of the United Nations, working in partnership with African Union and ECOWAS, helped uphold the will of the Gambian people and support a peaceful democratic transition. We have not forgotten that solidarity. It taught us that preventive diplomacy is not an abstract concept. It is a practical instrument for preventing confrontation, creating space for dialogue, and protecting institutions. Sometimes it can change the course of a That experience also gives us an If the international community could stand with the Gambia at a moment of fragility, then countries facing similar moments should be able to count on the same solidarity. Across the world, however, conflicts continue to destroy lives, displace populations, and reverse decades of Civilians bear the greatest cost, while humanitarian workers operate under increasingly dangerous conditions, and the resources available to respond to crisis remain far below what is The protection of civilians, respect for international humanitarian law, and humanitarian access are not political conveniences."},{"t":408,"topic":"conflict prevention","text":"They are legal obligations and expressions of our shared humanity. We need stronger early warning systems that enable us to act before crisis Timely mediation before positions become entrenched, and peacebuilding that addresses the conditions that allow conflict to take root. The question before us must therefore not only be how to end the ongoing wars, but how to prevent the next war from Prevention should not have to wait for a crisis to become sufficiently destructive to attract international attention. It is infinitely less costly in human, political, and financial terms to to prevent conflict than to manage its consequences after violence has begun. We therefore welcome the Secretary General's continued good offices and in preventing diplomacy and call for these efforts to be matched with predictable and sustained resources. Mr. President, peace must be built and nurtured through institutions that command public confidence, societies in which trust can be restored and justice pursued, and a future in which women and young people have a meaningful voice and economic opportunity is within reach."},{"t":480,"topic":"Gambia peacebuilding","text":"The Gambia has experienced the value of peacebuilding firsthand. Since our democratic transition, this Peacebuilding Commission and the Secretary-General's Peacebuilding Forum have been steadfast partners in our nationally led efforts to strengthen institutions, advance trans-transitional justice, and consolidate peace. We therefore support a stronger and more responsive Peacebuilding Commission, adequately resourced to support countries emerging from conflict or navigating delicate political The implementation of the outcomes of the Peacebuilding Architecture Review must translate into stronger prevention, greater national ownership, and closer coordination across the United Nations We also reaffirm our support for United Nations peacebuilding operations and pay tribute to the men and women who serve under the UN flag, including Gambian military and police personnel who have contributed with distinction to international peace and security. Their safety and security must remain a priority alongside performance, accountability, and strict adherence to international law."},{"t":549,"topic":"Sudan","text":"Partnerships between the United Nations and regional organizations, particularly the African Union, must also be deepened with sustained and predictable funding. Mr. President, the ongoing conflict in Sudan remains a matter of profound concern to the Gambia, together with continued instability across part of the Sahel. It reminds us that peace cannot be separated from development and The suffering of civilians in the affected conflict zones globally demands sustained international attention and renewed diplomatic efforts towards the escalation, dialogue, and a durable in the Sahel and other conflict zones. Our responses must be comprehensive and Security measures are necessary, but they must be accompanied by increased support for democratic governance, institution building, education, job creation, development, and climate Mr. President, for millions of people around the world, poverty, lack of human rights, democratic governance, etc. continue to pose greater insecurity."},{"t":612,"topic":"Gambia democracy","text":"The absence of education, health care, decent employment, and the loss of homes and livelihoods to climate change leave communities as vulnerable as conflict Our understanding of security must therefore extend beyond the absence of war to include the conditions that allow people to live with dignity, opportunity, and hope. Mr. President, in the Gambia, this understanding has guided our democratic journey from 2017 to date. We have undertaken the develop difficult work of rebuilding institutions, strengthening the rule of law, expanding access to justice, and confronting the legacy of past human rights violations. Our transitional justice process continues through implementation of the recommendation of the Truth, Reconciliation, and Reparations We have strengthened institutional accountability, established a special prosecution office to advance investigations and prosecution arising from the TRRC process. We are proud of the progress we have made, but we remain conscious that democracy is never a finished project and requires continuous institutional strengthening, adherence to rule of law, constitutional order, dialogue, and consensus building on issues."},{"t":682,"topic":"Gambia elections","text":"On the 5th of December, 2026, the Gambian people will again exercise their sovereign democratic right to choose their president. This will be another important milestone in our democratic journey, and we need the support of the international community in this regard. Our government is committed to ensuring that the elections are peaceful, credible, and inclusive and conducted in accordance with our constitution, national laws, and democratic standards. This is the democratic path the Gambia remains committed to pursuing, a path in which institutions are strengthened, citizens are heard, differences are resolved peacefully, and democratic gains are consolidated for future Mr. President, on development, the Gambia's recovery-focused national development plan provides the framework for accelerating our social and economic We are investing in roads, energy, schools, health care, agriculture, and digital infrastructure while promoting economic diversification, private sector investment, and value addition."},{"t":743,"topic":"Gambia development","text":"We are expanding opportunities for women and young people, improving lives, and strengthening the human capital upon which our future depends. I seize this opportunity to thank all the bilateral and multilateral partners of the Gambia for your continuous support and partnership. The global economic environment, Mr. President, remains particularly difficult for developing countries with declining official development assistance, high borrowing costs, disruptions in international trade, inflationary pressures, and food and energy insecurity, narrowing fiscal space, and threatening development gains. With only a few years remaining to achieve the 2030 agenda, the time for implementation is now. Following the fourth international conference on financing for development, we must translate the severe commitments to tangible action. Developing countries need greater access to affordable, long-term finance, meaningful reform of the multilateral development system, sustainable solutions to debt, stronger international tax cooperation, and decisive action against illicit financial flows."},{"t":807,"topic":"Gambia climate","text":"We also need stronger and more resilient supply chains, greater investment in productive capacity, and a global economic system that gives developing countries a fair opportunity to transform their economies. Trade must remain an engine of development, and developing countries must be enabled to participate more effectively in regional and global value The above would enable developing countries to invest in education, health, agriculture, climate resilience, and other productive sectors to holistically address their interconnected challenges. Mr. President, climate change presents another test of our collective credibility, and for The Gambia, it is not a distant threat. Coastal erosion, changing rainfall patterns, pressure on water resources, food insecurity, and environmental degradation are already affecting our communities and livelihoods. However, we are responding with determination by investing in renewable energy, coastal resilience, mangrove restoration, disaster risk reduction, early warning systems, water security, and nature-based nature-based solutions."},{"t":875,"topic":"Gambia energy","text":"National electricity access already 90% with universal access targeted by the end of 2026. We are expanding our solar energy in schools and health facilities, modernizing our electric electric network, and advancing a 150-MW solar park. We have also adopted our first national disaster risk mitigation plan. But we urge that our national ambition be supported by international action to make climate finance accessible, predictable, and adequate, including through the sustained implementation of the new collective quantified goal on climate finance, and effective management to address loss and build climate resilience, and a fairer international order in which those who have contributed least to the climate crisis are not left to bear the greatest Mr. President, artificial intelligence and emerging technologies offer extraordinary opportunities, but opportunity without inclusion can become another source of The digital divide must not become the next development divide."},{"t":939,"topic":"LDC technology","text":"Developing countries must not remain passive consumers of technologies designed elsewhere. We need the capacity to participate in research, innovation, entrepreneurship, and strengthening of global technology governance. Technology must serve humanity, and the governance of artificial intelligence must be inclusive, responsible, and grounded in international cooperation. This is particularly important for the world's least developed countries. As the Gambia prepares to assume greater leadership within the global coordination bureau of the LDC group, we do so with a clear sense of LDCs continue to face structural constraints, including limited productive capacity, high debt burdens, climate vulnerability, narrow export base, technological gaps, and restricted access to affordable finance. We will continue to advocate for full implementation of the Doha of action. Mr. President, migration is another area where our collective response must be guided by human dignity and shared responsibility."},{"t":1002,"topic":"UN reform","text":"Migration contributes significantly to development, cultural exchange, and human progress. Yet, irregular migration continues to expose young people and vulnerable populations to exploitation, trafficking, abuse, and tragic loss of We must strengthen cooperation for safe, orderly, and regular migration, protect the rights and dignity of migrants, and expand lawful pathways for labor mobility, as well as invest in young people, women, education, health, and social protection to safeguard sustainable development and lasting Mr. President, The Gambia welcomes the call for the reform of United Nation. We recognize the constraints facing the organization was limited with limited resources and increasing demands. This notwithstanding, the reforms must would strengthen the capacity of United Nations to serve its member states and the people of the world better as well as correct the historical injustice that continues to prevail. We need to embark on reforms that strengthen the legitimacy, protects universal character of the organization, and enable developing countries to participate meaningfully in that shape their future."},{"t":1076,"topic":"crimes against humanity","text":"Mr. President, the General Assembly's decision to move towards a convention on the prevention and punishment of crimes against humanity is an important contribution to addressing a long-standing gap in the international legal framework. The Gambia is proud of its leading role alongside Mexico in advancing this process through more than three decades of patient negotiation. Our conviction is simple. The gravest crimes cannot be met with silence. Victims cannot be forgotten. Impunity cannot become an accepted feature of international relations. Prevention, accountability, and justice are indispensable to reconciliation, healing, and sustainable peace. The rule of law is one of the foundation of on which trust is built. The continued development of multilateral treaties and the entry into force of the agreement on the conservation and sustainable use of marine biological diversity of areas beyond national jurisdiction also demonstrate what is possible when states negotiate in good faith and persevere."},{"t":1139,"topic":"Palestine","text":"The Gambia commends Ghana for its historic resolution on declaration of trafficking of enslaved Africans and racialized chattel enslavement of Africans as the gravest crime against humanity and to call for the resolution on correcting the map original assembly. Mr. President, our credibility is ultimately tested by how we respond to conflicts and crisis that remain unsolved for years. The suffering of the Palestinian people remains a profound test of the credibility of the international system. The Gambia reiterates its call for the protection of civilians, respect for international humanitarian law, and unhindered humanitarian assistance. We reaffirm the legitimate and inalienable rights of the Palestinian people, including their right to membership of United Nation, and our support for a just, comprehensive, and lasting two-state solution with Israel and Palestine living side-by-side in peace, security, and dignity. Furthermore, the plight of the Rohingya people must also not disappear from international agenda."},{"t":1204,"topic":"Cuba","text":"The Gambia affirms remains committed to accountability, justice, and the protection of their fundamental rights, and will continue to need the support of you all in this shared collective endeavor. On Cuba, we reiterate our long-standing call for an end to the economic, commercial, and financial sanctions. Dialogue, engagement, and cooperation remain important instruments for improving people's well-being and cementing peaceful relations among The Gambia also reaffirms its adherence to the one-China policy and values its partnership with the People's Republic of China, including in development cooperation, infrastructure, South-South and triangular cooperation, and partnership. The leaders of our two countries have raised our bilateral relations to strategic level, and we will continue to grow and deepen this important On the question of the Moroccan Sahara, The Gambia supports sustained international efforts towards a peaceful through the United Nations-led process political process. We encourage all concerned parties to engage constructively and in good faith."},{"t":1269,"topic":"Moroccan Sahara","text":"The real initiatives of Moroccan autonomy, the Moroccan-Nigeria gas pipeline, the Atlantic African initiative amongst others have provided realistic pathways to finding a lasting political solution to the dispute over the Moroccan Sahara by giving people the development, human rights, security, and stability they need. Furthermore, the Gambia welcomed the Kingdom of Morocco's continuous commitment to the ceasefire, full cooperation with MINURSO, and all also stakeholders all stakeholders in line with the resolution 2797 and other relevant We urge all stakeholders, i.e. Polisario, the Kingdom of Morocco, Algeria, and the Islamic Republic of Mauritania to continue working on achieving a sustainable political solution to the conflict, and we support the various initiatives of United Nations in this regard. Mr. President, in conclusion, United Nations and the multilateral system continue to be challenged, but they remain the most reliable guarantor of our collective peace and security and proven mechanisms to confront the challenges facing humanity."},{"t":1333,"topic":"UN reform","text":"the task before us is to make the United Nation the multilateral system more more representative, and better able to deliver for the people that we serve. What we leave behind should be a legacy of renewed multilateralism, a reformed United Nation, increased international cooperation and solidarity, and an increased trusted global system that sustains peace, advances development, human rights, democracy, and opens the way to a more secured future for all. The Gambia stands ready to work with every member state to renew the promise that brought the nations of the world together. My country's own journey has taught us that countries and institutions can evolve from moments of profound uncertainty and further build and create increased trust and confidence. This is the message that we bring to this assembly. I thank you for your kind &gt;&gt; On behalf of the assembly, I wish to thank the Vice President of the Republic of the Gambia."}],"compare":[{"topic":"International Law & Order","share":0.2155,"mean":0.0596,"rank":9,"others":102},{"topic":"UN & its reform","share":0.1081,"mean":0.2053,"rank":140,"others":170},{"topic":"Cuba","share":0.0521,"mean":0.0111,"rank":18,"others":23},{"topic":"Israel–Palestine","share":0.0519,"mean":0.0524,"rank":69,"others":76},{"topic":"Western Sahara","share":0.0504,"mean":0.0018,"rank":2,"others":4},{"topic":"Human Rights","share":0.0501,"mean":0.0084,"rank":16,"others":24},{"topic":"Sudan","share":0.0497,"mean":0.007,"rank":13,"others":15},{"topic":"Digital Divide","share":0.0496,"mean":0.0011,"rank":3,"others":3}]};
